(5781302, 841211, 60173, '<td valign="top">Yikes, that does suck!<br/> <br/>I can''t get over how awesome that tree is that''s directly above the cart in the photo.</td>', 'Yikes, that does suck! I can''t get over how awesome that tree is that''s directly above the cart in the photo.', '2009-12-25 23:44:46.000000', NULL, 1),
(5781303, 840838, 60173, '<td valign="top">Pretty nice shot, but completely title dependent.</td>', 'Pretty nice shot, but completely title dependent.', '2009-12-25 23:45:58.000000', NULL, 1),
