(5781307, 841146, 60173, '<td valign="top">I get more sadness than hatred, but the photo is excellent.</td>', 'I get more sadness than hatred, but the photo is excellent.', '2009-12-25 23:51:08.000000', NULL, 1),
(5781308, 840939, 60173, '<td valign="top">I understand this shot a bit better after a second look. I''m still not feeling the hate, because I know there''s a smile dying to come out there, but I can feel the vengeance.</td>', 'I understand this shot a bit better after a second look. I''m still not feeling the hate, because I know there''s a smile dying to come out there, but I can feel the vengeance.', '2009-12-25 23:54:27.000000', NULL, 1),
(5781309, 840770, 60173, '<td valign="top">This is one instance where I think the title actually says too much. The image is strong enough without the "I HATE YOU" in the title.</td>', 'This is one instance where I think the title actually says too much. The image is strong enough without the "I HATE YOU" in the title.', '2009-12-25 23:56:07.000000', NULL, 1),
