(5784790, 840745, 18197, '<td valign="top">LOVE the political commentary! Thanks for the smile!!!</td>', 'LOVE the political commentary! Thanks for the smile!!!', '2009-12-29 00:02:24.000000', NULL, 1),
(5784791, 841211, 18197, '<td valign="top">Me too! You''ve given the situation a realistic emotional payload. well done.</td>', 'Me too! You''ve given the situation a realistic emotional payload. well done.', '2009-12-29 00:03:14.000000', NULL, 1),
(5784792, 840838, 18197, '<td valign="top">This photo doesn''t convey hate to me ... except for you "shoehorn" title, of course. Still, it''s a great photo and I gave it a good score ...</td>', 'This photo doesn''t convey hate to me ... except for you "shoehorn" title, of course. Still, it''s a great photo and I gave it a good score ...', '2009-12-29 00:04:55.000000', NULL, 1),
(5784794, 841208, 18197, '<td valign="top">I''m baffled by your title ... but feel the photo fits the challenge very well.</td>', 'I''m baffled by your title ... but feel the photo fits the challenge very well.', '2009-12-29 00:05:35.000000', NULL, 1),
